    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter writer = new PrintWriter(System.out);
        int n = Integer.parseInt(reader.readLine().trim());
        if (n >= 100) {
            writer.print(0);
        } else {
            int[][] coords = new int[n+1][5];
            for (int i = 1; i <= n; i++) {
                StringTokenizer st = new StringTokenizer(reader.readLine());
                for (int j = 0; j < 5; j++) {
                    coords[i][j] = Integer.parseInt(st.nextToken());
                }
            }
            Set<Integer> excluded = new HashSet<>();
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    for (int k = 1; k <= n; k++) {
                        if (i == j || j == k || k == i) continue;
                        long[] diff1 = new long[5], diff2 = new long[5];
                        for (int m = 0; m < 5; m++) {
                            diff1[m] = coords[j][m] - coords[i][m];
                            diff2[m] = coords[k][m] - coords[i][m];
                        }
                        double dotProduct = 0;
                        long mag1 = 0, mag2 = 0;
                        for (int m = 0; m < 5; m++) {
                            dotProduct += diff1[m] * diff2[m];
                            mag1 += diff1[m] * diff1[m];
                            mag2 += diff2[m] * diff2[m];
                        }
                        double cosine = dotProduct / (Math.sqrt(mag1) * Math.sqrt(mag2));
