#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    if (n >= 100) {
        cout << 0 << "\n";
    } else {
        vector<vector<int>> coords(n + 1, vector<int>(5));
        for (int i = 1; i <= n; i++) {
            for (int j = 0; j < 5; j++) {
                cin >> coords[i][j];
            }
        }
        unordered_set<int> excluded;
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                for (int k = 1; k <= n; k++) {
                    if (i == j || j == k || k == i) continue;
                    std::vector<long long> diff1(5), diff2(5);
                    for (int m = 0; m < 5; m++) {
                        diff1[m] = coords[j][m] - coords[i][m];
                        diff2[m] = coords[k][m] - coords[i][m];
                    }
                    long double dotProduct = 0.0;
                    long long mag1 = 0, mag2 = 0;
                    for (int m = 0; m < 5; m++) {
                        dotProduct += (long double)diff1[m] * diff2[m];
                        mag1 += diff1[m] * diff1[m];
                        mag2 += diff2[m] * diff2[m];
                    }
                    long double denom = sqrtl((long double)mag1) * sqrtl((long double)mag2);
                    if (denom == 0) continue; // avoid division by zero
                    long double cosine = dotProduct / denom;
                    long double angle = acosl(cosine) * 180.0 / M_PI;
                    if (angle + 1e-9 < 90.0) {
                        excluded.insert(i);
                    }
                }
            }
        }
        cout << n - (int)excluded.size() << "\n";
        for (int i = 1; i <= n; i++) {
            if (excluded.find(i) == excluded.end()) {
                cout << i << "\n";
            }
        }
    }
    return 0;
}
